"""Builds cycles/017/ethereum-reference.research.json from the results in this work directory."""
import json, os
W = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(os.path.dirname(W), 'ethereum-reference.research.json')

def load(n):
    p = os.path.join(W, n)
    return json.load(open(p)) if os.path.exists(p) else None

def summ(d, key='results'):
    if not d: return 'not run'
    parts = []
    for r in d[key]:
        parts.append(f"{r['name']}: {r['ran']}/{r['vectors']} ran, {r['mismatchCount']} mismatches")
    return '; '.join(parts)

bat, batp = load('battery4.json'), load('battery-pocket.json')
tar, tarp = load('targeted.json'), load('targeted-pocket.json')
pmd = load('pmdiff.json')
pd = load('pushdup.json')
hk = load('hooks7702.json')

bat_txt = summ(bat) + ('; ' + summ(batp) if batp else '')
tar_txt = summ(tar) + ('; ' + summ(tarp) if tarp else '')

def pm_txt():
    if not pmd: return 'not run'
    s = [f"{r['name']}: {r['identical']} of 250 scripts identical to reth v2.11.0, {r['different']} different, {r['errors']} errors" for r in pmd['results']]
    return 'reference reth v2.11.0 returned 11,892 calls (11,225 succeed, 667 revert); ' + '; '.join(s) + '. geth v1.17.5 and reth v2.7.0 were not run with pmdiff this cycle'

pd_txt = '; '.join(f"{k}: {v['match']} of {v['programs']} equal, {v['mismatch']} differ, {v['errors']} refused" for k, v in pd.items())

